package com.medicare360.appointment; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/appointments") @CrossOrigin(origins="http://localhost:4200") public class AppointmentController { private final AppointmentRepository repo; public AppointmentController(AppointmentRepository repo){this.repo=repo;} @GetMapping public List<Appointment> all(){return repo.findAll();} @PostMapping public Appointment create(@RequestBody Appointment a){if(a.getStatus()==null)a.setStatus("BOOKED");return repo.save(a);} @PutMapping("/{id}/status") public Appointment status(@PathVariable Long id,@RequestParam String value){Appointment a=repo.findById(id).orElseThrow();a.setStatus(value.toUpperCase());return repo.save(a);} @DeleteMapping("/{id}") public void cancel(@PathVariable Long id){Appointment a=repo.findById(id).orElseThrow();a.setStatus("CANCELLED");repo.save(a);} @GetMapping("/count") public Map<String,Long> count(){return Map.of("total",repo.count(),"booked",repo.countByStatus("BOOKED"),"completed",repo.countByStatus("COMPLETED"));} }